const B64="";
const DATA=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(B64),c=>c.charCodeAt(0))));
export async function getCategoryFeed({tagId,timestamp}={}){const feed=DATA[String(tagId??"")]||{tagTitle:"Categoria",items:[],nextTimestamp:null};return {items:Array.isArray(feed.items)?feed.items:[],nextTimestamp:feed.nextTimestamp??null,tagTitle:feed.tagTitle};}
export default {getCategoryFeed};
